*{box-sizing:border-box} :root{color-scheme:dark;--bg:#060b11;--panel:#0b141e;--line:#1a2a38;--muted:#758999;--white:#e9f4f8;--cyan:#45d9f4;--blue:#56a9ff;--red:#ff545a;--gold:#e5b960} html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--bg);color:var(--white);font-family:'Rajdhani',sans-serif}body{background-image:radial-gradient(ellipse at 50% 43%,#0b1b28 0%,#060b11 68%)}button{color:inherit;font:inherit}.game-shell{height:100dvh;min-height:500px;max-width:1800px;margin:auto;padding:17px 26px 15px;display:grid;grid-template-rows:92px minmax(0,1fr) 102px;gap:15px}.topbar{position:relative;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #1b2b39;padding:0 6px 12px}.brand{display:flex;gap:13px;align-items:center;min-width:248px}.brand-mark{width:37px;height:42px;position:relative;display:flex;align-items:center;justify-content:center;gap:3px;filter:drop-shadow(0 0 7px #43d5f466)}.brand-mark span{display:block;width:5px;height:29px;border:1px solid #4bd7f2;transform:skewY(-28deg);border-radius:1px}.brand-mark span:nth-child(2){height:39px;background:#48d6ed1c}.eyebrow,.stat-label,.controls-label small,.action-copy small,.action-cost small,.bottom-meta,.arena-caption,.hint,.objective small,.modal-kicker,.shop-note,.upgrade small,.boss-title span{font-family:'DM Mono',monospace;letter-spacing:.11em}.eyebrow{font-size:9px;color:#7292a4;margin-bottom:3px}.brand h1{font-size:22px;letter-spacing:.055em;font-weight:600;line-height:1;margin:0;color:#e5f1f5}.brand h1 b{color:#56d9ef;font-weight:700}.status-grid{display:grid;grid-template-columns:1.04fr 1.04fr .8fr .78fr;gap:17px;align-items:center;flex:1;max-width:790px;margin:0 40px}.stat{height:48px;border-left:1px solid #233441;padding-left:13px}.stat-label{font-size:9px;color:#8296a3;display:flex;justify-content:space-between;align-items:center;white-space:nowrap;gap:5px}.stat-label b{color:#d8e6e9;font-size:11px;font-weight:500;letter-spacing:.04em}.status-dot{height:6px;width:6px;border-radius:100%;display:inline-block;margin-right:5px}.status-dot.red{background:#ff6262;box-shadow:0 0 8px #f44}.status-dot.blue{background:#48d9ff;box-shadow:0 0 8px #48d9ff}.meter{height:3px;background:#1a2a36;margin-top:8px;overflow:hidden}.meter i{height:100%;display:block;width:100%;background:#df555b;box-shadow:0 0 8px #fa5c66;transition:width .3s}.force-stat .meter i{background:#4dd7ef;box-shadow:0 0 8px #4dd7ef}.wave-number{display:flex;align-items:baseline;gap:3px;margin-top:0}.wave-number b{font-size:25px;line-height:1;color:#e7f2f4}.wave-number span{font-family:'DM Mono',monospace;color:#718794;font-size:11px}.wave-number em{font-family:'DM Mono',monospace;font-style:normal;color:#e4bb68;font-size:8px;letter-spacing:.08em;margin-left:4px}.score-stat .stat-label{display:block}.score-stat .stat-label b{float:right}.credits{margin-top:3px;font-size:20px;line-height:1;color:#e9f4f3}.credits span,.shop-coins span{color:#e5b960;font-size:17px;margin-right:4px}.credits small{font-family:'DM Mono',monospace;font-size:8px;color:#8397a1;letter-spacing:.09em}.sound-button{position:absolute;right:4px;top:3px;border:1px solid #253744;background:#0b151e;color:#a6bbc5;padding:6px 9px;font-size:16px;cursor:pointer}.sound-button span{font:8px 'DM Mono';margin-left:5px;letter-spacing:.1em}.arena-wrap{min-height:0;position:relative}.arena-frame{height:100%;width:100%;position:relative;overflow:hidden;border:1px solid #1c3444;background:#07111a;box-shadow:0 0 0 4px #071018,0 12px 50px #0008,inset 0 0 60px #102e4155}canvas{width:100%;height:100%;display:block;touch-action:none}.arena-frame:before,.arena-frame:after{content:'';position:absolute;z-index:2;width:20px;height:20px;pointer-events:none;border-color:#50c9e6;border-style:solid;opacity:.65}.arena-frame:before{left:-1px;top:-1px;border-width:1px 0 0 1px}.arena-frame:after{right:-1px;bottom:-1px;border-width:0 1px 1px 0}.arena-caption{position:absolute;left:17px;top:14px;z-index:3;font-size:9px;color:#7e9aaa;pointer-events:none}.live-dot{display:inline-block;width:5px;height:5px;background:#42d7ef;border-radius:100%;box-shadow:0 0 8px #42d7ef;margin-right:7px;vertical-align:1px}.caption-divider{padding:0 6px;color:#3c5664}.hint{position:absolute;bottom:15px;left:50%;transform:translateX(-50%);z-index:3;color:#8195a2;font-size:8px;white-space:nowrap;letter-spacing:.15em;pointer-events:none}.objective{position:absolute;right:18px;top:14px;z-index:3;display:flex;align-items:center;gap:8px;color:#84a4b3;pointer-events:none}.objective-icon{font-size:24px;color:#53d9ed;text-shadow:0 0 12px #4adfff;line-height:1}.objective b{display:block;font:9px 'DM Mono';letter-spacing:.09em}.objective small{display:block;color:#637986;font-size:7px;margin-top:3px}.wave-banner{position:absolute;z-index:3;left:50%;top:16%;transform:translate(-50%,-10px);display:flex;gap:12px;align-items:center;background:#08131bdc;border:1px solid #315367;padding:8px 14px;opacity:0;transition:.35s;pointer-events:none}.wave-banner.show{opacity:1;transform:translate(-50%,0)}.wave-banner span{font:10px 'DM Mono';color:#54d9ed;letter-spacing:.1em}.wave-banner b{font:600 11px 'DM Mono';color:#e9c16e;letter-spacing:.08em}.toast{position:absolute;z-index:5;left:50%;top:56px;transform:translate(-50%,-10px);opacity:0;padding:8px 13px;background:#111e28;border:1px solid #395569;color:#c5e1e9;font:10px 'DM Mono';letter-spacing:.06em;transition:.2s;white-space:nowrap;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.boss-status{display:none;position:absolute;top:48px;left:50%;transform:translateX(-50%);width:min(310px,55%);z-index:3}.boss-status.active{display:block}.boss-title{font:9px 'DM Mono';color:#ff696e;letter-spacing:.1em;display:flex;justify-content:space-between;margin-bottom:5px}.boss-title span{font-size:7px;color:#be6b70}.boss-meter{height:5px;background:#38171c;border:1px solid #73343a}.boss-meter i{display:block;background:#ff4148;height:100%;width:100%;transition:width .2s;box-shadow:0 0 7px #ff3338}.bottom-bar{display:flex;align-items:center;gap:18px;border-top:1px solid #1a2b38;padding:12px 6px 0}.controls-label{min-width:176px;display:flex;gap:11px;align-items:center}.control-line{height:29px;width:2px;background:#47cde2;box-shadow:0 0 7px #46dff4}.controls-label b{font-size:13px;letter-spacing:.09em;display:block}.controls-label small{font-size:7px;color:#728795;display:block;margin-top:3px}.action-buttons{display:flex;gap:9px;flex:1}.action-button{height:59px;background:linear-gradient(115deg,#101d28,#0b141d);border:1px solid #203544;display:flex;align-items:center;gap:10px;text-align:left;padding:7px 12px;flex:1;min-width:0;cursor:pointer;transition:border-color .15s,background .15s;position:relative}.action-button:hover{border-color:#3e8498;background:#10212c}.action-button.selected{border-color:#48d8ed;background:#10303b;box-shadow:0 0 15px #35cce622}.action-button:disabled{opacity:.42;cursor:not-allowed}.action-icon{width:30px;height:30px;display:grid;place-items:center;border:1px solid #2d6675;color:#58d4e5;background:#0a232d;font-size:20px;flex:none}.turret-icon{border-color:#3d5984;color:#78aefa;background:#101b30}.action-copy{min-width:0;flex:1}.action-copy b{font-size:12px;letter-spacing:.04em;display:block;white-space:nowrap}.action-copy small{font-size:7px;color:#8194a0;display:block;margin-top:3px;white-space:nowrap;letter-spacing:.06em}.action-cost{text-align:right;border-left:1px solid #293945;padding-left:9px;color:#e5c16e;font:13px 'DM Mono';white-space:nowrap}.action-cost small{font-size:7px;color:#907d55}.force-button{flex:1}.cooldown-ring{width:31px;height:31px;border:1px solid #4e90a2;border-radius:50%;display:grid;place-items:center;color:#57dced;position:relative;font-size:17px;flex:none}.cooldown-ring i{position:absolute;inset:-1px;border:2px solid #45d6ed;border-left-color:transparent;border-bottom-color:transparent;border-radius:50%;transform:rotate(45deg);transition:transform .2s}.force-button.cooling .cooldown-ring{color:#72858d;border-color:#30424c}.force-button.cooling .cooldown-ring i{border-color:#768b95;border-left-color:transparent;border-bottom-color:transparent}.force-key{font:9px 'DM Mono';border:1px solid #2a3c48;padding:3px 5px;color:#778a95}.bottom-meta{min-width:110px;text-align:right;font-size:7px;color:#637884;letter-spacing:.08em}.bottom-meta .version{display:block;margin-top:7px}.bottom-meta i{font-style:normal;color:#4cd2e8}.modal{position:absolute;inset:0;z-index:10;display:grid;place-items:center;background:#03090dd9;backdrop-filter:blur(5px);padding:16px}.modal.hidden{display:none}.modal-card{width:min(440px,100%);background:linear-gradient(145deg,#101d27,#09121b);border:1px solid #2b5364;padding:23px 27px 19px;text-align:center;position:relative;box-shadow:0 14px 80px #000c,inset 0 1px #6ad8e61c}.modal-card:before,.modal-card:after{content:'';position:absolute;width:13px;height:13px;border-color:#56d9ed;border-style:solid}.modal-card:before{top:-1px;left:-1px;border-width:1px 0 0 1px}.modal-card:after{bottom:-1px;right:-1px;border-width:0 1px 1px 0}.modal-kicker{font-size:8px;color:#76a4b2;letter-spacing:.16em}.modal-emblem,.end-symbol{font-size:27px;color:#62dff0;text-shadow:0 0 20px #55d9ed88;margin:6px 0 -3px}.modal-card h2{font-size:29px;letter-spacing:.12em;margin:3px 0;color:#eff8f8;font-weight:700}.modal-copy{font-size:13px;color:#95aab4;margin:0 0 14px;letter-spacing:.03em}.shop-coins{font:9px 'DM Mono';letter-spacing:.08em;color:#9eb0b6;margin:11px 0}.shop-coins b{font-size:17px;color:#f0d082;margin-right:5px}.upgrade-list{display:grid;gap:7px;margin:11px 0 14px}.upgrade{background:#0b161f;border:1px solid #233b49;padding:9px 10px;display:flex;align-items:center;text-align:left;gap:10px;cursor:pointer}.upgrade:hover:not(:disabled){border-color:#4bc8db}.upgrade:disabled{opacity:.43;cursor:not-allowed}.upgrade-icon{width:29px;height:29px;display:grid;place-items:center;color:#5ad5e7;font-size:17px;background:#102832}.upgrade span:nth-child(2){flex:1}.upgrade b{display:block;font-size:12px;letter-spacing:.08em}.upgrade small{display:block;font-size:7px;color:#7e929c;margin-top:2px}.upgrade strong{font:11px 'DM Mono';color:#e8c875;white-space:nowrap}.upgrade strong small{display:inline;color:#917e56}.primary-button{width:100%;padding:11px 14px;border:1px solid #45cfe4;background:linear-gradient(90deg,#10313b,#114653);font:600 12px 'Rajdhani';letter-spacing:.13em;color:#d9f8fa;cursor:pointer;box-shadow:0 0 18px #42d4ea1a}.primary-button:hover{background:#176174}.primary-button span{float:right;font-size:16px;line-height:12px}.shop-note{font-size:7px;color:#607985;letter-spacing:.1em;margin-top:11px}.end-card{width:min(410px,100%);padding:29px 30px 24px}.end-card h2{font-size:30px}.end-card .modal-copy{margin:4px 0 17px}.end-symbol{font-size:37px;margin:13px 0 5px}.final-score{display:flex;justify-content:space-between;align-items:center;border-top:1px solid #203541;border-bottom:1px solid #203541;padding:10px 0;margin:15px 0;font:9px 'DM Mono';color:#8096a1;letter-spacing:.1em}.final-score b{font-size:19px;color:#eacb7c}.end-card.loss .end-symbol{color:#ff666c;text-shadow:0 0 20px #fa475e66}.end-card.loss h2{color:#ff8a8e}
@media(max-width:850px){.game-shell{padding:12px 14px;grid-template-rows:95px minmax(0,1fr) 96px;gap:10px}.brand{min-width:195px}.brand h1{font-size:18px}.eyebrow{font-size:7px}.status-grid{gap:9px;margin:0 35px 0 6px}.stat{padding-left:8px}.stat-label{font-size:7px}.stat-label b{font-size:9px}.bottom-bar{gap:9px}.controls-label{min-width:138px}.controls-label b{font-size:11px}.action-button{gap:7px;padding:6px 8px}.action-copy b{font-size:10px}.action-copy small{font-size:6px}.action-cost{font-size:11px;padding-left:6px}.bottom-meta{min-width:66px}.desktop-hint{display:none}}
@media(max-width:600px){html,body{overflow:hidden}.game-shell{height:100dvh;min-height:0;padding:8px 9px 9px;grid-template-rows:106px minmax(0,1fr) 130px;gap:8px}.topbar{align-items:flex-start;padding:0 2px 6px}.brand{min-width:0;position:absolute;left:2px;top:2px;gap:7px}.brand-mark{width:25px;height:28px}.brand-mark span{height:20px;width:3px}.brand-mark span:nth-child(2){height:27px}.eyebrow{font-size:6px}.brand h1{font-size:15px}.sound-button{right:1px;top:0;padding:3px 5px;font-size:12px}.sound-button span{font-size:6px}.status-grid{position:absolute;left:0;right:0;bottom:6px;margin:0;max-width:none;grid-template-columns:1fr 1fr .8fr .72fr;gap:5px}.stat{height:43px;padding-left:6px}.stat-label{font-size:6px;letter-spacing:.05em}.stat-label b{font-size:8px}.meter{margin-top:7px}.wave-number b{font-size:20px}.wave-number em{font-size:6px;margin-left:1px}.credits{font-size:16px}.credits small{font-size:6px}.arena-caption{left:9px;top:9px;font-size:7px}.objective{top:8px;right:8px;gap:5px}.objective-icon{font-size:19px}.objective b{font-size:7px}.objective small{font-size:5px}.hint{bottom:8px;font-size:6px;letter-spacing:.08em}.wave-banner{top:18%;padding:6px 9px}.wave-banner span,.wave-banner b{font-size:8px}.toast{top:39px;font-size:8px}.boss-status{top:39px}.boss-title{font-size:7px}.boss-title span{font-size:6px}.bottom-bar{padding:6px 0 0;display:block;position:relative}.controls-label{display:none}.action-buttons{height:100%;gap:5px}.action-button{height:100%;padding:7px 5px;flex-direction:column;justify-content:center;align-items:center;gap:4px;text-align:center}.action-icon{height:26px;width:26px;font-size:17px}.action-copy{flex:none}.action-copy b{font-size:8px;letter-spacing:.025em}.action-copy small{font-size:5px;white-space:normal;line-height:1.3;margin-top:2px}.action-cost{border:0;padding:0;font-size:9px;line-height:1;color:#e8c875}.action-cost small{display:inline;font-size:6px}.cooldown-ring{height:27px;width:27px;font-size:15px}.force-key{display:none}.force-button{gap:4px}.bottom-meta{display:none}.modal{padding:10px}.modal-card{padding:19px 18px 15px}.modal-card h2{font-size:25px}.modal-copy{font-size:11px}.shop-note{font-size:6px}}
@media(max-height:560px) and (min-width:601px){.game-shell{grid-template-rows:72px minmax(0,1fr) 80px;padding-top:8px;padding-bottom:8px;gap:8px}.brand-mark{height:34px}.brand-mark span{height:24px}.brand-mark span:nth-child(2){height:32px}.action-button{height:51px}.bottom-bar{padding-top:7px}.modal-card{padding-top:15px;padding-bottom:13px}}

(() => {
  'use strict';
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const $ = (id) => document.getElementById(id);
  const ui = { healthText:$('healthText'),healthBar:$('healthBar'),forceText:$('forceText'),forceBar:$('forceBar'),waveText:$('waveText'),waveState:$('waveState'),scoreText:$('scoreText'),creditsText:$('creditsText'),hint:$('hint'),waveBanner:$('waveBanner'),toast:$('toast'),shop:$('shopModal'),end:$('endModal'),shopCredits:$('shopCredits'),next:$('nextWave'),force:$('forceButton'),forceSub:$('forceSub'),sweep:$('cooldownSweep'),boss:$('bossStatus'),bossBar:$('bossBar') };
  const W=1000,H=600,NODE={x:500,y:300};
  let dpr=1, screenW=0,screenH=0,last=0, gameState='playing',wave=1,health=100,force=100,credits=120,score=0,selected=null,toastTimer=0,bannerTimer=0,spawnTimer=1.2,spawned=0,spawnTotal=0,forceCooldown=0,shotClock=0,heroSpeed=245,heroDamage=32,muted=false;
  let hero={x:500,y:420,tx:500,ty:420,angle:-Math.PI/2,step:0};
  let enemies=[],bolts=[],towers=[],effects=[];
  const rand=(a,b)=>a+Math.random()*(b-a), clamp=(v,a,b)=>Math.max(a,Math.min(b,v)), dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
  function resize(){const r=canvas.getBoundingClientRect();screenW=r.width;screenH=r.height;dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);ctx.setTransform(canvas.width/W,0,0,canvas.height/H,0,0)}
  new ResizeObserver(resize).observe(canvas); resize();
  function toast(msg){ui.toast.textContent=msg;ui.toast.classList.add('show');toastTimer=2.2}
  function banner(title,subtitle=''){ui.waveBanner.innerHTML=`<span>${title}</span><b>${subtitle}</b>`;ui.waveBanner.classList.add('show');bannerTimer=2.2}
  function updateHud(){ui.healthText.textContent=`${Math.ceil(health)}%`;ui.healthBar.style.width=`${health}%`;ui.forceText.textContent=`${Math.floor(force)}%`;ui.forceBar.style.width=`${force}%`;ui.waveText.textContent=String(wave).padStart(2,'0');ui.scoreText.textContent=String(score).padStart(6,'0');ui.creditsText.textContent=credits;ui.shopCredits.textContent=credits;ui.boss.classList.toggle('active',enemies.some(e=>e.boss));const boss=enemies.find(e=>e.boss);if(boss)ui.bossBar.style.width=`${100*boss.hp/boss.maxHp}%`;ui.force.disabled=forceCooldown>0;ui.force.classList.toggle('cooling',forceCooldown>0);ui.forceSub.textContent=forceCooldown>0?`COOLDOWN · ${Math.ceil(forceCooldown)} SEC`:'AREA BLAST · READY';ui.sweep.style.transform=`rotate(${45+Math.max(0,forceCooldown)/10*360}deg)`;document.querySelectorAll('.action-button[data-build]').forEach(b=>b.disabled=credits<(b.dataset.build==='pylon'?50:70));}
  function pointer(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width*W,y:(e.clientY-r.top)/r.height*H}}
  canvas.addEventListener('pointerdown',e=>{if(gameState!=='playing')return;const p=pointer(e);if(selected){placeTower(p);return}hero.tx=clamp(p.x,45,955);hero.ty=clamp(p.y,55,555);hero.step=0});
  document.querySelectorAll('.action-button[data-build]').forEach(b=>b.addEventListener('click',()=>{if(gameState!=='playing')return;const kind=b.dataset.build,cost=kind==='pylon'?50:70;if(credits<cost){toast('NOT ENOUGH CREDITS');return}selected=selected===kind?null:kind;document.querySelectorAll('.action-button[data-build]').forEach(x=>x.classList.toggle('selected',x.dataset.build===selected));ui.hint.textContent=selected?`TAP THE ARENA TO PLACE ${selected==='pylon'?'SHIELD PYLON':'BLASTER TURRET'} · ESC CANCELS`:'TAP THE ARENA TO MOVE · SELECT A DEFENSE TO DEPLOY'};canvas.style.cursor=selected?'crosshair':'default'}));
  function placeTower(p){const cost=selected==='pylon'?50:70;if(credits<cost){toast('NOT ENOUGH CREDITS');return}if(Math.hypot(p.x-NODE.x,p.y-NODE.y)<73){toast('CANNOT BUILD ON ARCHIVE NODE');return}if(towers.some(t=>dist(t,p)<38)){toast('DEFENSE GRID IS OCCUPIED');return}credits-=cost;towers.push({x:p.x,y:p.y,type:selected,cooldown:rand(.1,.8),pulse:0});effects.push({x:p.x,y:p.y,r:4,max:selected==='pylon'?37:29,life:.45,color:'#50d9ec'});toast(selected==='pylon'?'SHIELD PYLON DEPLOYED':'BLASTER TURRET DEPLOYED');selected=null;document.querySelectorAll('.action-button[data-build]').forEach(x=>x.classList.remove('selected'));ui.hint.textContent='TAP THE ARENA TO MOVE · SELECT A DEFENSE TO DEPLOY';canvas.style.cursor='default';updateHud()}
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&selected){selected=null;document.querySelectorAll('.action-button[data-build]').forEach(x=>x.classList.remove('selected'));ui.hint.textContent='TAP THE ARENA TO MOVE · SELECT A DEFENSE TO DEPLOY';canvas.style.cursor='default'}if(e.key.toLowerCase()==='f')forcePush()});
  ui.force.addEventListener('click',forcePush);
  function forcePush(){if(gameState!=='playing'||forceCooldown>0)return;if(force<25){toast('INSUFFICIENT FORCE ENERGY');return}force-=25;forceCooldown=10;effects.push({x:hero.x,y:hero.y,r:20,max:245,life:.65,color:'#55e9fa',blast:true});let hit=0;for(const e of enemies){const d=dist(hero,e);if(d<215){const dx=e.x-hero.x,dy=e.y-hero.y,l=Math.max(1,Math.hypot(dx,dy));e.hp-=heroDamage*1.6;e.knockX=dx/l*190;e.knockY=dy/l*190;e.hit=.22;hit++}}toast(`FORCE PUSH · ${hit} TARGET${hit===1?'':'S'} HIT`);if(!muted)beep(170,.18,'sine',.055);updateHud()}
  function beginWave(n){wave=n;gameState='playing';spawned=0;spawnTotal=5+n*2;spawnTimer=.65;enemies=[];bolts=[];ui.shop.classList.add('hidden');ui.waveState.textContent='INCOMING';banner(`WAVE ${String(n).padStart(2,'0')}`,n===5?'BOSS INBOUND':'INCOMING');if(n===5)spawnTotal=9;updateHud()}
  ui.next.addEventListener('click',()=>beginWave(wave+1));
  function shop(){gameState='shop';ui.waveState.textContent='SECURED';ui.shop.classList.remove('hidden');updateHud()}
  $('speedUpgrade').addEventListener('click',()=>buyUpgrade('speed'));
  $('damageUpgrade').addEventListener('click',()=>buyUpgrade('damage'));
  function buyUpgrade(type){const cost=type==='speed'?75:90;if(credits<cost){toast('NOT ENOUGH CREDITS');return}credits-=cost;if(type==='speed'){heroSpeed+=45;$('speedUpgrade').disabled=true;$('speedUpgrade').querySelector('strong').textContent='OWNED'}else{heroDamage+=12;$('damageUpgrade').disabled=true;$('damageUpgrade').querySelector('strong').textContent='OWNED'}updateHud();if(!muted)beep(540,.07,'sine',.035)}
  function endGame(win){gameState=win?'won':'lost';ui.end.classList.remove('hidden');const card=ui.end.querySelector('.modal-card');card.classList.toggle('loss',!win);$('endTitle').textContent=win?'TEMPLE PRESERVED!':'TEMPLE FALLEN';$('endCopy').textContent=win?'The Jedi archives remain secure. The Force is in balance.':'The archive node has been breached. The Jedi Temple has fallen.';$('endKicker').textContent=win?'MISSION COMPLETE · ARCHIVES SECURED':'MISSION FAILED · ARCHIVE BREACHED';$('endSymbol').textContent=win?'✧':'✕';$('finalScore').textContent=String(score).padStart(6,'0');$('restartButton').textContent=win?'PLAY AGAIN  ↻':'TRY AGAIN  ↻';}
  $('restartButton').addEventListener('click',()=>{health=100;force=100;credits=120;score=0;wave=1;heroSpeed=245;heroDamage=32;hero={x:500,y:420,tx:500,ty:420,angle:-Math.PI/2,step:0};enemies=[];bolts=[];towers=[];effects=[];forceCooldown=0;selected=null;$('speedUpgrade').disabled=false;$('damageUpgrade').disabled=false;$('speedUpgrade').querySelector('strong').innerHTML='75 <small>CR</small>';$('damageUpgrade').querySelector('strong').innerHTML='90 <small>CR</small>';ui.end.classList.add('hidden');beginWave(1)});
  function spawnEnemy(){const boss=wave===5&&spawned===0,side=Math.random()<.5?0:1;const y=rand(110,490);const hp=boss?760:58+wave*17;enemies.push({x:side===0?-20:1020,y,hp,maxHp:hp,boss,side,speed:boss?23:rand(37,49)+wave*2,fire:rand(.7,2),hit:0,knockX:0,knockY:0,anim:rand(0,6.2),flash:0});spawned++;if(boss){banner('WAVE 05','SENTINEL DROID');toast('WARNING · SENTINEL DROID DETECTED')}}
  function update(dt){if(gameState==='playing'){
    force=Math.min(100,force+2.6*dt);forceCooldown=Math.max(0,forceCooldown-dt);const dx=hero.tx-hero.x,dy=hero.ty-hero.y,d=Math.hypot(dx,dy);if(d>2){const m=Math.min(d,heroSpeed*dt);hero.x+=dx/d*m;hero.y+=dy/d*m;hero.angle=Math.atan2(dy,dx);hero.step+=dt*12}
    if(spawned<spawnTotal){spawnTimer-=dt;if(spawnTimer<=0){spawnEnemy();spawnTimer=wave===5?1.18:Math.max(.7,1.3-wave*.08)}}
    for(const t of towers){t.cooldown-=dt;t.pulse+=dt; if(t.type==='turret'&&t.cooldown<=0){let target=null,md=390;for(const e of enemies){const d=dist(t,e);if(d<md){md=d;target=e}}if(target){bolts.push({x:t.x,y:t.y-9,tx:target.x,ty:target.y,owner:'friendly',speed:410,damage:38+heroDamage*.18});t.cooldown=.88;effects.push({x:t.x,y:t.y,r:3,max:17,life:.2,color:'#5bdafa'})}}}
    for(const e of enemies){const nearestPylon=towers.filter(t=>t.type==='pylon').some(t=>dist(t,e)<135);let vx=NODE.x-e.x,vy=NODE.y-e.y,len=Math.max(1,Math.hypot(vx,vy));let speed=e.speed*(nearestPylon?.58:1);if(e.knockX||e.knockY){e.x+=e.knockX*dt;e.y+=e.knockY*dt;e.knockX*=Math.pow(.04,dt);e.knockY*=Math.pow(.04,dt)}e.x+=vx/len*speed*dt;e.y+=vy/len*speed*dt;e.anim+=dt*5;e.fire-=dt;e.hit=Math.max(0,e.hit-dt);e.flash=Math.max(0,e.flash-dt);if(e.fire<=0&&dist(e,hero)>60){const aim=dist(e,hero)<280?hero:NODE;bolts.push({x:e.x,y:e.y-4,tx:aim.x+rand(-12,12),ty:aim.y+rand(-12,12),owner:'enemy',speed:e.boss?220:260,damage:e.boss?8:5});e.fire=rand(e.boss?1.05:1.6,e.boss?1.6:2.5)}if(len<28){health=Math.max(0,health-(e.boss?22:14));effects.push({x:NODE.x,y:NODE.y,r:15,max:66,life:.42,color:'#ff5d63'});e.hp=0;toast('ARCHIVE NODE UNDER ATTACK')}}
    for(const b of bolts){const dx=b.tx-b.x,dy=b.ty-b.y,l=Math.hypot(dx,dy)||1,m=Math.min(l,b.speed*dt);b.x+=dx/l*m;b.y+=dy/l*m;b.life=(b.life||0)+dt;if(b.owner==='enemy'&&dist(b,hero)<23){b.owner='friendly';let target=null,md=Infinity;for(const e of enemies){const de=dist(hero,e);if(de<md){md=de;target=e}}if(target){b.tx=target.x;b.ty=target.y;b.damage=heroDamage;b.speed=470;b.deflected=true;effects.push({x:hero.x,y:hero.y,r:3,max:22,life:.22,color:'#b9f5ff'});if(!muted)beep(790,.035,'triangle',.012)}else b.life=5}if(b.life>4||Math.hypot(b.x-b.tx,b.y-b.ty)<9)b.dead=true;if(b.owner==='friendly'){const target=enemies.find(e=>dist(e,b)<(e.boss?35:22));if(target){target.hp-=b.damage;target.flash=.12;b.dead=true;effects.push({x:b.x,y:b.y,r:3,max:16,life:.24,color:'#5be5fb'})}}}
    bolts=bolts.filter(b=>!b.dead);for(const e of enemies){if(e.hp<=0){score+=e.boss?2500:100+wave*15;credits+=e.boss?160:18;effects.push({x:e.x,y:e.y,r:8,max:e.boss?78:35,life:.45,color:e.boss?'#ff6469':'#58dbed'});e.dead=true}}enemies=enemies.filter(e=>!e.dead);
    for(const fx of effects){fx.life-=dt;if(fx.blast)fx.r+=(fx.max-fx.r)*Math.min(1,dt*9);else fx.r+=(fx.max-fx.r)*dt*8}effects=effects.filter(f=>f.life>0);
    if(health<=0){health=0;endGame(false)}else if(spawned>=spawnTotal&&enemies.length===0){if(wave===5)endGame(true);else shop()}
   }else{for(const fx of effects){fx.life-=dt;fx.r+=(fx.max-fx.r)*dt*6}effects=effects.filter(f=>f.life>0)}
   if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}if(bannerTimer>0){bannerTimer-=dt;if(bannerTimer<=0)ui.waveBanner.classList.remove('show')}updateHud();}

