function path(points){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);}
function drawBackground(){
  const g=ctx.createLinearGradient(0,0,1000,600);g.addColorStop(0,'#08131d');g.addColorStop(.5,'#0b1922');g.addColorStop(1,'#08131b');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
  // Archive floor and luminous inlaid geometry.
  ctx.save();ctx.strokeStyle='#234052';ctx.lineWidth=1;ctx.globalAlpha=.27;
  for(let x=45;x<1000;x+=65){path([[x,50],[x,550]]);ctx.stroke()}for(let y=78;y<560;y+=58){path([[35,y],[965,y]]);ctx.stroke()}
  ctx.restore();
  const floorGlow=ctx.createRadialGradient(500,300,30,500,300,450);floorGlow.addColorStop(0,'#11304326');floorGlow.addColorStop(1,'#06101a00');ctx.fillStyle=floorGlow;ctx.fillRect(0,0,W,H);
  // Opposing archive alcoves.
  for(let side=0;side<2;side++){const x=side===0?0:1000,dir=side===0?1:-1;ctx.save();ctx.globalAlpha=.75;
    for(let j=0;j<5;j++){const y=104+j*91;ctx.fillStyle='#0a1822';ctx.strokeStyle='#244354';ctx.lineWidth=1;ctx.fillRect(side===0?8:884,y,108,58);ctx.strokeRect(side===0?8:884,y,108,58);ctx.fillStyle='#102532';ctx.fillRect(side===0?18:894,y+8,88,41);ctx.fillStyle='#246378';ctx.globalAlpha=.32;ctx.fillRect(side===0?21:897,y+12,82,2);ctx.globalAlpha=.75;ctx.fillStyle='#172c37';ctx.fillRect(side===0?24:900,y+18,75,3);ctx.fillRect(side===0?24:900,y+26,64,3);ctx.fillRect(side===0?24:900,y+34,71,3);ctx.fillStyle='#57d6eb';ctx.globalAlpha=.6;ctx.fillRect(side===0?110:880,y+4,2,49);ctx.globalAlpha=.75}
    // luminous side rails
    ctx.strokeStyle='#37a6c4';ctx.globalAlpha=.16;ctx.lineWidth=2;path([[side===0?128:872,65],[side===0?128:872,535]]);ctx.stroke();ctx.restore()}
  // Approach lanes converge on the archive.
  ctx.save();ctx.setLineDash([6,10]);ctx.lineWidth=1;ctx.strokeStyle='#54c9dd';ctx.globalAlpha=.15;path([[20,130],[300,185],[500,300]]);ctx.stroke();path([[20,470],[300,415],[500,300]]);ctx.stroke();path([[980,130],[700,185],[500,300]]);ctx.stroke();path([[980,470],[700,415],[500,300]]);ctx.stroke();ctx.setLineDash([]);ctx.restore();
  // Decoratively segmented chamber rings.
  ctx.save();ctx.translate(NODE.x,NODE.y);for(let r of [112,164,224]){ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.strokeStyle=r===112?'#367184':'#244657';ctx.globalAlpha=r===112?.25:.14;ctx.lineWidth=r===112?1.2:1;ctx.stroke()}ctx.globalAlpha=.28;ctx.strokeStyle='#52d1e4';ctx.lineWidth=1;for(let i=0;i<16;i++){const a=i*Math.PI/8;ctx.beginPath();ctx.moveTo(Math.cos(a)*174,Math.sin(a)*174);ctx.lineTo(Math.cos(a)*188,Math.sin(a)*188);ctx.stroke()}ctx.restore();
  // Floor panels in the central aisle.
  ctx.save();ctx.globalAlpha=.18;ctx.strokeStyle='#315565';for(let x=260;x<=740;x+=80){ctx.strokeRect(x,246,64,108)}ctx.restore();
  // Archive node pedestal.
  ctx.save();ctx.translate(NODE.x,NODE.y);ctx.shadowColor='#36d6f4';ctx.shadowBlur=18;const pulse=.5+.5*Math.sin(performance.now()*.002);
  ctx.fillStyle='#0b2633';ctx.strokeStyle='#4fd9ed';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(0,0,44+pulse*2,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.strokeStyle='#337d91';ctx.beginPath();ctx.arc(0,0,35,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#153f4c';ctx.beginPath();ctx.moveTo(0,-27);ctx.lineTo(22,0);ctx.lineTo(0,27);ctx.lineTo(-22,0);ctx.closePath();ctx.fill();ctx.strokeStyle='#75ecf5';ctx.lineWidth=1.4;ctx.stroke();ctx.fillStyle='#a5faff';ctx.globalAlpha=.65+.35*pulse;ctx.beginPath();ctx.arc(0,0,5+pulse*2,0,Math.PI*2);ctx.fill();ctx.restore();
  // Path threat markers.
  for(const x of [36,964]){ctx.save();ctx.translate(x,300);ctx.fillStyle='#ff5a5d';ctx.globalAlpha=.45;ctx.beginPath();ctx.moveTo(x<500?7:-7,0);ctx.lineTo(x<500?-5:-5,-6);ctx.lineTo(x<500?-5:-5,6);ctx.closePath();ctx.fill();ctx.restore()}
}
function drawPylon(t){ctx.save();ctx.translate(t.x,t.y);const p=.5+.5*Math.sin(t.pulse*3);ctx.strokeStyle='#4fe3ee';ctx.globalAlpha=.12+.08*p;ctx.lineWidth=1;ctx.beginPath();ctx.arc(0,0,135,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=.7;ctx.shadowColor='#43d8e6';ctx.shadowBlur=9;ctx.fillStyle='#0e2d38';ctx.strokeStyle='#53dbea';ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(0,-17);ctx.lineTo(13,-6);ctx.lineTo(10,11);ctx.lineTo(0,17);ctx.lineTo(-10,11);ctx.lineTo(-13,-6);ctx.closePath();ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#9af5f3';ctx.fillRect(-2, -11,4,22);ctx.fillRect(-8,-2,16,3);ctx.restore()}
function drawTurret(t){ctx.save();ctx.translate(t.x,t.y);ctx.rotate(t.pulse*.2);ctx.strokeStyle='#70aaff';ctx.globalAlpha=.13;ctx.lineWidth=1;ctx.beginPath();ctx.arc(0,0,96,0,Math.PI*2);ctx.stroke();ctx.rotate(-t.pulse*.2);ctx.shadowColor='#458eff';ctx.shadowBlur=10;ctx.fillStyle='#111f31';ctx.strokeStyle='#71aaff';ctx.lineWidth=1.3;ctx.beginPath();ctx.arc(0,0,15,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#419bef';ctx.beginPath();ctx.arc(0,0,5,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#7db7ff';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(0,-4);ctx.lineTo(0,-14);ctx.stroke();ctx.restore()}
function drawHero(){ctx.save();ctx.translate(hero.x,hero.y);ctx.rotate(hero.angle+Math.PI/2);ctx.shadowColor='#4fe3ff';ctx.shadowBlur=15;ctx.globalAlpha=.2;ctx.fillStyle='#54d8ee';ctx.beginPath();ctx.ellipse(0,10,19,24,0,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;ctx.shadowBlur=0;
  // robe silhouette
  ctx.fillStyle='#162a38';ctx.strokeStyle='#8fd7e6';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(-12,13);ctx.lineTo(-9,-1);ctx.lineTo(-6,-8);ctx.lineTo(6,-8);ctx.lineTo(10,-1);ctx.lineTo(13,13);ctx.lineTo(8,16);ctx.lineTo(-8,16);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#b8d8dc';ctx.beginPath();ctx.arc(0,-12,6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#dfb66c';ctx.fillRect(6,-2,3,14);
  // ignited blue lightsaber
  ctx.shadowColor='#45dffc';ctx.shadowBlur=14;ctx.strokeStyle='#a8fbff';ctx.lineWidth=2.3;ctx.beginPath();ctx.moveTo(8,-1);ctx.lineTo(8,-34);ctx.stroke();ctx.strokeStyle='#38cdec';ctx.lineWidth=5;ctx.globalAlpha=.42;ctx.beginPath();ctx.moveTo(8,-3);ctx.lineTo(8,-32);ctx.stroke();ctx.restore();
  ctx.save();ctx.globalAlpha=.3;ctx.strokeStyle='#54dff2';ctx.beginPath();ctx.arc(hero.x,hero.y,25,0,Math.PI*2);ctx.stroke();ctx.restore()
}
function drawEnemy(e){ctx.save();ctx.translate(e.x,e.y);if(e.knockX)ctx.rotate(e.knockX*.001);const scale=e.boss?1.7:1;ctx.scale(scale,scale);const bob=Math.sin(e.anim)*1.5;ctx.translate(0,bob);ctx.shadowColor=e.boss?'#ff3e48':'#f4434e';ctx.shadowBlur=e.boss?14:7;ctx.fillStyle=e.flash?'#f5d8d1':e.boss?'#482128':'#371c25';ctx.strokeStyle=e.flash?'#fff':e.boss?'#ff6269':'#f45c64';ctx.lineWidth=1.15;
  // armored body and head
  ctx.beginPath();ctx.moveTo(-9,8);ctx.lineTo(-12,-1);ctx.lineTo(-8,-9);ctx.lineTo(8,-9);ctx.lineTo(12,-1);ctx.lineTo(9,8);ctx.lineTo(5,11);ctx.lineTo(-5,11);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#6f3038';ctx.fillRect(-7,-8,14,7);ctx.fillStyle='#ff5c62';ctx.fillRect(-5,-6,3,2);ctx.fillRect(2,-6,3,2);ctx.fillStyle='#452129';ctx.fillRect(-14,0,5,3);ctx.fillRect(9,0,5,3);ctx.fillStyle='#87404a';ctx.fillRect(-6,11,4,5);ctx.fillRect(3,11,4,5);
  // rifle
  ctx.strokeStyle='#9f5157';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-3,4);ctx.lineTo(-15,8);ctx.lineTo(-19,8);ctx.stroke();ctx.shadowBlur=0;
  if(e.boss){ctx.fillStyle='#ff555d';ctx.fillRect(-19,-20,38,2);ctx.fillStyle='#ff494f';ctx.fillRect(-19,-20,38*e.hp/e.maxHp,2)}else if(e.hp<e.maxHp){ctx.fillStyle='#382328';ctx.fillRect(-11,-17,22,2);ctx.fillStyle='#fa6368';ctx.fillRect(-11,-17,22*e.hp/e.maxHp,2)}ctx.restore()}
function drawBolt(b){const dx=b.tx-b.x,dy=b.ty-b.y,a=Math.atan2(dy,dx);ctx.save();ctx.translate(b.x,b.y);ctx.rotate(a);ctx.shadowColor=b.owner==='friendly'?'#43efff':'#ff343e';ctx.shadowBlur=b.deflected?14:9;ctx.strokeStyle=b.owner==='friendly'?'#79f5ff':'#ff5660';ctx.lineWidth=b.owner==='friendly'?2.4:2;ctx.beginPath();ctx.moveTo(-9,0);ctx.lineTo(7,0);ctx.stroke();ctx.strokeStyle='#fff';ctx.lineWidth=.8;ctx.beginPath();ctx.moveTo(-4,0);ctx.lineTo(5,0);ctx.stroke();ctx.restore()}

