  function drawBolt(b){const dx=b.tx-b.x,dy=b.ty-b.y,a=Math.atan2(dy,dx);ctx.save();ctx.translate(b.x,b.y);ctx.rotate(a);ctx.shadowColor=b.owner==='friendly'?'#43efff':'#ff343e';ctx.shadowBlur=b.deflected?14:9;ctx.strokeStyle=b.owner==='friendly'?'#79f5ff':'#ff5660';ctx.lineWidth=b.owner==='friendly'?2.4:2;ctx.beginPath();ctx.moveTo(-9,0);ctx.lineTo(7,0);ctx.stroke();ctx.strokeStyle='#fff';ctx.lineWidth=.8;ctx.beginPath();ctx.moveTo(-4,0);ctx.lineTo(5,0);ctx.stroke();ctx.restore()}
